func minAssignmentCost(cost [][]int) int {
	n := len(cost)
	if n == 0 {
		return 0
	}
	const unreached = 1 << 60
	dp := make([]int, 1<<n)
	for i := range dp {
		dp[i] = unreached
	}
	dp[0] = 0
	for mask := 0; mask < 1<<n; mask++ {
		if dp[mask] == unreached {
			continue
		}
		worker := popcount(mask)
		if worker == n {
			continue
		}
		for task := 0; task < n; task++ {
			if mask&(1<<task) != 0 {
				continue
			}
			next := mask | 1<<task
			if c := dp[mask] + cost[worker][task]; c < dp[next] {
				dp[next] = c
			}
		}
	}
	return dp[1<<n-1]
}

func popcount(mask int) int {
	n := 0
	for m := mask; m != 0; m &= m - 1 {
		n++
	}
	return n
}
