// stronglyConnectedComponents returns the SCCs of the directed graph, using
// Kosaraju: an order by finish time on the graph, then components on its
// reverse.
func stronglyConnectedComponents(n int, edges [][]int) [][]int {
	adj := make([][]int, n)
	rev := make([][]int, n)
	for _, e := range edges {
		adj[e[0]] = append(adj[e[0]], e[1])
		rev[e[1]] = append(rev[e[1]], e[0])
	}

	// First pass: push each node after all of its out-neighbours are done.
	order := make([]int, 0, n)
	seen := make([]bool, n)
	iter := make([]int, n)
	for s := 0; s < n; s++ {
		if seen[s] {
			continue
		}
		seen[s] = true
		stack := []int{s}
		for len(stack) > 0 {
			u := stack[len(stack)-1]
			if iter[u] < len(adj[u]) {
				v := adj[u][iter[u]]
				iter[u]++
				if !seen[v] {
					seen[v] = true
					stack = append(stack, v)
				}
				continue
			}
			order = append(order, u)
			stack = stack[:len(stack)-1]
		}
	}

	// Second pass: reachability in the reverse graph, taking roots in
	// decreasing finish time.
	comps := make([][]int, 0)
	done := make([]bool, n)
	for i := len(order) - 1; i >= 0; i-- {
		s := order[i]
		if done[s] {
			continue
		}
		done[s] = true
		comp := []int{s}
		for j := 0; j < len(comp); j++ {
			u := comp[j]
			for _, v := range rev[u] {
				if !done[v] {
					done[v] = true
					comp = append(comp, v)
				}
			}
		}
		comps = append(comps, comp)
	}
	return comps
}
