func TestParallelMapRespectsWorkerLimit(t *testing.T) {
	const workers = 4
	items := make([]int, 40)
	for i := range items {
		items[i] = i
	}
	var inFlight, peak int64
	var mu sync.Mutex
	parallelMap(items, workers, func(v int) int {
		now := atomic.AddInt64(&inFlight, 1)
		mu.Lock()
		if now > peak {
			peak = now
		}
		mu.Unlock()
		time.Sleep(10 * time.Millisecond)
		atomic.AddInt64(&inFlight, -1)
		return v
	})
	mu.Lock()
	defer mu.Unlock()
	if peak > workers {
		t.Fatalf("saw %d calls in flight at once, the limit was %d", peak, workers)
	}
	if peak < workers {
		t.Fatalf("never got past %d calls in flight, %d workers were allowed", peak, workers)
	}
}

